{
  "id": "r:6704f4d5e6e48906:t1:s:scene",
  "title": "寒林初诞",
  "location": "青石村",
  "blocks": [
    {
      "kind": "narration",
      "text": "寒风穿过林间的缝隙，吹动了摇篮边的草席。云归在这一年的冬日里降生，周围是简陋的土屋与粗糙的农具。村里的长辈们低声议论着，似乎在谈论着这孩子眼中透出的异样神采。"
    },
    {
      "kind": "dialogue",
      "text": "这孩子生得倒是个硬朗模样，只是这眼神，瞧着不像个寻常农家娃。",
      "speaker": "r:6704f4d5e6e48906:t1:e:elder"
    },
    {
      "kind": "narration",
      "text": "一名年迈的村民站在摇篮旁，目光在云归身上停留了许久，随后转头看向屋外的风雪。"
    }
  ],
  "entities": [
    {
      "id": "r:6704f4d5e6e48906:t1:e:elder",
      "name": "村中长辈",
      "kind": "person",
      "status": "alive"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:e:village",
      "name": "青石村",
      "kind": "place"
    }
  ],
  "choices": [
    {
      "id": "r:6704f4d5e6e48906:t1:c:a",
      "label": "在襁褓中啼哭",
      "intent": "explore",
      "targetId": "relic",
      "stake": "low",
      "approach": "cautious"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:c:b",
      "label": "静静观察四周",
      "intent": "explore",
      "targetId": "relic",
      "stake": "low",
      "approach": "cautious"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:c:c",
      "label": "试图抓握身边的物件",
      "intent": "explore",
      "targetId": "supplies",
      "stake": "low",
      "approach": "cautious"
    }
  ],
  "memoryDeltas": [
    {
      "entityId": "self",
      "text": "出生于青石村，天生具备过目不忘与剑骨之资。"

    ,
      "kind": "fact"
    }
  ]
}

{
  "id": "r:6704f4d5e6e48906:t1:s:scene",
  "title": "启程",
  "location": "r:6704f4d5e6e48906:t1:e:starting_village",
  "entities": [
    {
      "id": "r:6704f4d5e6e48906:t1:e:starting_village",
      "name": "青石村",
      "kind": "place"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:e:village_elder",
      "name": "村长",
      "kind": "person"
    }
  ],
  "blocks": [
    {
      "kind": "narration",
      "text": "十六岁的云归背起简单的行囊，站在青石村的村口。晨雾尚未散尽，远处的山峦在薄雾中若隐若现，那是他从未涉足过的未知世界。"
    },
    {
      "kind": "dialogue",
      "text": "云归，外面的世界可不像村里这么太平，若遇上不长眼的修士，记得收敛些性子。",
      "speaker": "r:6704f4d5e6e48906:t1:e:village_elder"
    },
    {
      "kind": "narration",
      "text": "村长递过一袋干粮，目光中既有期许，也藏着一丝担忧。云归点了点头，望着通往山脉的小径，心中那股不安分的劲头正蠢蠢欲动。"
    }
  ],
  "choices": [
    {
      "id": "r:6704f4d5e6e48906:t1:c:a",
      "label": "前往后山寻找修行之法",
      "intent": "practice",
      "targetId": "self",
      "stake": "low",
      "approach": "steady"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:c:b",
      "label": "深入林间搜寻物资",
      "intent": "explore",
      "targetId": "supplies",
      "stake": "low",
      "approach": "cautious"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:c:c",
      "label": "离开村庄前往城镇",
      "intent": "travel",
      "targetId": "r:6704f4d5e6e48906:t1:e:starting_village",
      "stake": "low",
      "approach": "road"
    }
  ],
  "memoryDeltas": [
    {
      "entityId": "self",
      "text": "云归决定离开青石村开始修行之路。"

{
  "id": "r:6704f4d5e6e48906:t1:s:scene",
  "title": "青石村的清晨",
  "location": "青石村",
  "entities": [
    {
      "id": "r:6704f4d5e6e48906:t1:e:person_OldMan_Li",
      "name": "李老头",
      "kind": "person",
      "status": "alive"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:e:place_QingshiVillage",
      "name": "青石村",
      "kind": "place"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:e:place_NorthMountain",
      "name": "北山",
      "kind": "place"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:e:place_VillageMarket",
      "name": "村口集市",
      "kind": "place"
    }
  ],
  "blocks": [
    {
      "kind": "narration",
      "text": "晨雾未散，青石村的石板路泛着湿意。你今年十六岁，身体里没有任何灵气流转，是个彻头彻尾的凡人。但你的记忆极好，且天生对剑意有莫名的亲近感。腰间挂着三件简单的补给，口袋里空空如也。"
    },
    {
      "kind": "dialogue",
      "text": "云归，别在那发呆。听说北山深处的‘听剑崖’最近有异象，不少散修都往那边赶。你虽然没修为，但脑子灵光，去碰碰运气也好，总比在家种地强。",
      "speaker": "r:6704f4d5e6e48906:t1:e:person_OldMan_Li"
    },
    {
      "kind": "narration",
      "text": "李老头拄着拐杖，眯着眼看向村口。集市上人来人往，偶尔有背着行囊的修士路过，引来村民们的窃窃私语。北山方向云雾缭绕，隐约传来风声。"
    }
  ],
  "choices": [
    {
      "id": "r:6704f4d5e6e48906:t1:c:a",
      "label": "前往北山探查异象",
      "intent": "travel",
      "targetId": "r:6704f4d5e6e48906:t1:e:place_NorthMountain",
      "stake": "high",
      "approach": "road"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:c:b",
      "label": "在村口集市打听消息",
      "intent": "negotiate",
      "targetId": "r:6704f4d5e6e48906:t1:e:person_OldMan_Li",
      "stake": "low",
      "approach": "cooperate"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:c:c",
      "label": "在原地尝试感应灵气",
      "intent": "practice",
      "targetId": "self",
      "stake": "low",
      "approach": "steady"
    }
  ]
,
  "memoryDeltas": [
    {
      "entityId": "r:6704f4d5e6e48906:t1:e:person_OldMan_Li",
      "text": "李老头建议云归去北山听剑崖碰碰运气，认为他脑子灵光。"
    ,
      "kind": "fact"
    }
  ]
}

{
  "id": "r:6704f4d5e6e48906:t2:s:scene",
  "title": "北山听剑崖",
  "location": "北山",
  "entities": [
    {
      "id": "r:6704f4d5e6e48906:t1:e:place_NorthMountain",
      "name": "北山",
      "kind": "place"
    },
    {
      "id": "r:6704f4d5e6e48906:t2:e:person_WanderingSwordsman",
      "name": "游方剑客",
      "kind": "person",
      "status": "alive"
    }
  ],
  "blocks": [
    {
      "kind": "narration",
      "text": "三十日跋涉，云归终于抵达北山深处。此处云雾缭绕，崖壁如削，风过处竟有隐隐剑鸣之声。崖边杂草丛生，隐约可见一处被藤蔓遮蔽的石台，石台中央似乎刻着模糊的纹路。"
    },
    {
      "kind": "dialogue",
      "text": "小子，你身上有剑骨，却无剑意。这听剑崖的剑鸣，凡人听了只会头痛欲裂，你竟能走到这里，倒是有些意思。",
      "speaker": "r:6704f4d5e6e48906:t2:e:person_WanderingSwordsman"
    },
    {
      "kind": "narration",
      "text": "一名灰袍男子不知何时出现在石台旁，手中把玩着一枚生锈的铁片。他目光如电，上下打量着云归，嘴角挂着一丝玩味的笑意。"
    }
  ],
  "choices": [
    {
      "id": "r:6704f4d5e6e48906:t2:c:a",
      "label": "询问剑客关于剑鸣的来历",
      "intent": "negotiate",
      "targetId": "r:6704f4d5e6e48906:t2:e:person_WanderingSwordsman",
      "stake": "low",
      "approach": "cooperate"
    },
    {
      "id": "r:6704f4d5e6e48906:t2:c:b",
      "label": "探查石台上的模糊纹路",
      "intent": "explore",
      "targetId": "relic",
      "stake": "high",
      "approach": "cautious"
    },
    {
      "id": "r:6704f4d5e6e48906:t2:c:c",
      "label": "趁其不备逃离北山",
      "intent": "evade",
      "targetId": "r:6704f4d5e6e48906:t2:e:person_WanderingSwordsman",
      "stake": "high",
      "approach": "conceal"
    }
  ],
  "memoryDeltas": [
    {
      "entityId": "r:6704f4d5e6e48906:t2:e:person_WanderingSwordsman",
      "text": "游方剑客出现在听剑崖，认出云归有剑骨，并提及听剑崖剑鸣对凡人的危害。"
    , "kind": "fact"
    }
  ]
}

{
  "id": "r:6704f4d5e6e48906:t2:s:scene",
  "title": "集市余音",
  "location": "村口集市",
  "entities": [
    {
      "id": "r:6704f4d5e6e48906:t1:e:person_OldMan_Li",
      "name": "李老头",
      "kind": "person",
      "status": "alive"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:e:place_VillageMarket",
      "name": "村口集市",
      "kind": "place"
    },
    {
      "id": "r:6704f4d5e6e48906:t1:e:place_NorthMountain",
      "name": "北山",
      "kind": "place"
    }
  ],
  "blocks": [
    {
      "kind": "narration",
      "text": "集市的人流渐渐散去，李老头的身影在摊位间若隐若现。你手里攥着刚换来的灵石，指尖微凉。"
    },
    {
      "kind": "dialogue",
      "text": "“小子，北山的路不好走，但剑崖的风声能磨掉凡人的杂念。记住，别贪多。”",
      "speaker": "r:6704f4d5e6e48906:t1:e:person_OldMan_Li"
    },
    {
      "kind": "narration",
      "text": "他摆摆手，转身消失在人群里。你望着北山方向，云雾缭绕，不知深浅。"
    }
  ],
  "choices": [
    {
      "id": "r:6704f4d5e6e48906:t2:c:a",
      "label": "立刻动身前往北山",
      "intent": "travel",
      "targetId": "r:6704f4d5e6e48906:t1:e:place_NorthMountain",
      "stake": "low",
      "approach": "road"
    },
    {
      "id": "r:6704f4d5e6e48906:t2:c:b",
      "label": "在集市寻找北山地图",
      "intent": "explore",
      "targetId": "relic",
      "stake": "low",
      "approach": "bold"
    },
    {
      "id": "r:6704f4d5e6e48906:t2:c:c",
      "label": "向李老头追问剑崖细节",
      "intent": "negotiate",
      "targetId": "r:6704f4d5e6e48906:t1:e:person_OldMan_Li",
      "stake": "low",
      "approach": "cooperate"
    }
  ],
  "memoryDeltas": [
    {
      "entityId": "r:6704f4d5e6e48906:t1:e:person_OldMan_Li",
      "text": "李老头提醒云归北山路难走，剑崖风声可磨杂念，且不可贪多。"
    ,
      "kind": "fact"
    }
  ]
}
